# Public Reproduction

Run the offline reproduction from the task root:

```bash
python reproduce.py
```

The script first checks that the supplied project launcher can start, then runs
an ordinary offline distance-dependent contact-analysis workflow. It writes
`outputs/public_reproduction_report.json` and returns a nonzero status while
the supplied historical implementation cannot produce the requested report. A
successful repair produces a finite, nonempty analysis report and returns
zero. Timeout, import, input, or launcher failures are reported separately as
`runner_failure`.

The report is intentionally a smoke-level observation. It reports only whether
the project-level analysis produced a usable report. It does not inspect output
field names, compare numerical values, request a whole-map aggregate, or
enumerate all scientific behaviors used for evaluation.
from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

import numpy as np
import pandas as pd


TASK_DIR = Path(__file__).resolve().parent
SOURCE_DIR = TASK_DIR / "source"
ARCHIVE_PATH = TASK_DIR / "fixtures" / "archive_contact_map.cool"
OUTPUT_DIR = TASK_DIR / "outputs"
ANALYSIS_PATH = OUTPUT_DIR / "contact_decay.tsv"
REPORT_PATH = OUTPUT_DIR / "public_reproduction_report.json"


def write_report(payload: dict[str, object], exit_code: int) -> int:
    OUTPUT_DIR.mkdir(exist_ok=True)
    serialized = json.dumps(payload, indent=2, sort_keys=True) + "\n"
    REPORT_PATH.write_text(serialized, encoding="utf-8")
    print(serialized, end="")
    return exit_code


def check_inputs() -> None:
    required_paths = (ARCHIVE_PATH, SOURCE_DIR / "run_cli.py")
    missing = [str(path.relative_to(TASK_DIR)) for path in required_paths if not path.exists()]
    if missing:
        raise FileNotFoundError("Required task input is unavailable.")


def has_usable_report() -> bool:
    table = pd.read_csv(ANALYSIS_PATH, sep="\t")
    if table.empty:
        return False
    numeric = table.select_dtypes(include="number")
    return bool(numeric.shape[1] and np.isfinite(numeric.to_numpy()).any())


def main() -> int:
    try:
        check_inputs()
        OUTPUT_DIR.mkdir(exist_ok=True)
        if ANALYSIS_PATH.exists():
            ANALYSIS_PATH.unlink()
        probe = subprocess.run(
            [sys.executable, str(SOURCE_DIR / "run_cli.py"), "--help"],
            cwd=TASK_DIR,
            capture_output=True,
            text=True,
            check=False,
            timeout=120,
        )
        if probe.returncode != 0:
            return write_report(
                {"schema_version": "1.0", "status": "runner_failure"}, 2
            )
        command = [
            sys.executable,
            str(SOURCE_DIR / "run_cli.py"),
            "expected-cis",
            str(ARCHIVE_PATH),
            "--output",
            str(ANALYSIS_PATH),
            "--smooth",
            "--clr-weight-name",
            "",
            "--ignore-diags",
            "1",
            "--nproc",
            "1",
        ]
        result = subprocess.run(
            command,
            cwd=TASK_DIR,
            capture_output=True,
            text=True,
            check=False,
            timeout=300,
        )
    except subprocess.TimeoutExpired:
        return write_report({"schema_version": "1.0", "status": "runner_failure"}, 2)
    except Exception:
        return write_report({"schema_version": "1.0", "status": "runner_failure"}, 2)

    if result.returncode != 0:
        return write_report(
            {
                "schema_version": "1.0",
                "status": "pre_fix_expected_failure",
                "observation": "The requested contact-decay report was not produced."
            },
            1,
        )

    try:
        usable = has_usable_report()
    except Exception:
        return write_report({"schema_version": "1.0", "status": "runner_failure"}, 2)

    if not usable:
        return write_report(
            {
                "schema_version": "1.0",
                "status": "pre_fix_expected_failure",
                "observation": "The workflow completed without a usable scientific report."
            },
            1,
        )

    return write_report(
        {
            "schema_version": "1.0",
            "status": "workflow_completed",
            "observation": "The candidate workflow produced a non-empty finite report."
        },
        0,
    )


if __name__ == "__main__":
    raise SystemExit(main())

{
  "observation": "The requested contact-decay report was not produced.",
